const api = () => window.go?.main?.AgentApp;
const notice = document.querySelector('#notice');
function report(message, error = false) { notice.textContent = message || ''; notice.dataset.error = error ? 'true' : 'false'; }
async function refresh() { try { const state = await api().State(); document.querySelector('#hostname').textContent = state.hostname || 'Tailscale unavailable'; document.querySelector('#config').textContent = state.configurationNote; document.querySelector('#report').textContent = state.bootstrapNote; document.querySelector('#bootstrap-note').textContent = state.bootstrapReady ? 'Machine bootstrap is complete.' : 'Install the local GPU prerequisites, CUDA RPC server, firewall rules, and Agent config.'; document.querySelector('#pair-note').textContent = state.paired ? 'This machine already trusts its paired Orchestrator.' : 'Open a short-lived code window only when the Orchestrator is ready.'; document.querySelector('#service-note').textContent = state.serviceDetail || (state.serviceRunning ? 'Agent is listening.' : 'Start after local setup and pairing.'); document.querySelector('#provision').hidden = !state.canProvision; document.querySelector('#provision').disabled = state.bootstrapReady; document.querySelector('#open-pair').disabled = state.pairingActive || state.serviceRunning; document.querySelector('#start-service').disabled = !state.configured || !state.paired || state.serviceRunning; document.querySelector('#stop-service').disabled = !state.serviceRunning; document.querySelector('#code-panel').hidden = !state.pairingActive; document.querySelector('#pair-code').textContent = state.pairingCode || ''; report(''); } catch (error) { report(error.message || String(error), true); } }
document.querySelector('#refresh').addEventListener('click', refresh);
document.querySelector('#provision').addEventListener('click', async () => { try { report('Windows setup is running with elevation. If Tailscale is missing, a browser will open for its normal sign-in. llama.cpp can take several minutes to build.'); await api().StartProvisioning(); await refresh(); } catch (error) { report(error.message || String(error), true); } });
document.querySelector('#open-pair').addEventListener('click', async () => { try { await api().OpenPairing(); await refresh(); } catch (error) { report(error.message || String(error), true); } });
document.querySelector('#start-service').addEventListener('click', async () => { try { await api().StartService(); await refresh(); } catch (error) { report(error.message || String(error), true); } });
document.querySelector('#stop-service').addEventListener('click', async () => { try { await api().StopService(); await refresh(); } catch (error) { report(error.message || String(error), true); } });
window.addEventListener('DOMContentLoaded', () => { refresh(); setInterval(refresh, 5000); });
